{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Add uniform smooth pairwise ranking pressure to the existing weighted loss across all four datasets, using only valid positions and already sampled negatives. This may improve candidate ordering while preserving architecture, sampling, inference, and training settings.",
      "edits": [
        {
          "find": "    pairwise_loss = torch.nn.functional.softplus(valid_neg - valid_pos)\n    return (weights * pairwise_loss).sum()",
          "replace": "    pairwise_loss = torch.nn.functional.softplus(valid_neg - valid_pos)\n    return (weights * pairwise_loss).sum() + 0.05 * pairwise_loss.mean()"
        }
      ]
    }
  ],
  "change_summary": "Use L_existing + 0.05 * mean(softplus(s_negative - s_positive)). No predictor changes are needed."
}
